package main

// Golden output for the daemon's two source-tree walkers, copyTree and tarTree.
//
// The files under testdata/ were generated by the fs.WalkDir implementation
// these walkers had before they stopped following directory symlinks, and are
// what keeps that change silent: an ordinary tree must copy and tar exactly as
// it did. Regenerate only when an output change is intended:
//
//	TREE_WALK_GOLDEN_UPDATE=1 go test ./cmd/artifact-daemon/ -run TestTreeWalkGolden

import (
	"archive/tar"
	"bytes"
	"context"
	"crypto/sha256"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
	"syscall"
	"testing"
	"time"

	"golang.org/x/sys/unix"
)

const goldenTreeLoc = "steps/golden/out"

// goldenEpoch is a whole second so the tar header carries it without rounding.
var goldenEpoch = time.Date(2026, 1, 2, 3, 4, 5, 0, time.UTC)

// longGoldenName is one path component over tar's 100-byte name field, so the
// archive needs a PAX record for it.
var longGoldenName = strings.Repeat("long-name-", 15) + ".txt"

// buildGoldenTree lays out an ordinary artifact: files of several modes,
// nested and empty directories, in-tree relative symlinks to files and to
// directories, a hard link, mixed-case and non-ASCII names, a name too long
// for a plain tar header, and a fifo and a socket (which neither walker
// carries). Every mode and mtime is set explicitly so the output does not
// depend on the umask, the clock or the platform.
//
// No two names differ only by case: macOS's default filesystem folds case.
func buildGoldenTree(t *testing.T) string {
	t.Helper()
	store := t.TempDir()
	out := filepath.Join(store, filepath.FromSlash(goldenTreeLoc))

	type entry struct {
		name    string
		kind    byte // 'd' dir, 'f' file, 'l' symlink, 'h' hard link, 'p' fifo, 's' socket
		mode    os.FileMode
		content string // file content, or link target
	}
	// Parents before children; times are applied in reverse afterwards.
	entries := []entry{
		{"", 'd', 0o755, ""},
		{"a.txt", 'f', 0o644, "alpha\n"},
		{"exec.sh", 'f', 0o755, "#!/bin/sh\necho hi\n"},
		{"private", 'f', 0o600, "owner only\n"},
		{"empty.txt", 'f', 0o644, ""},
		{"dir", 'd', 0o755, ""},
		{"dir/nested", 'd', 0o700, ""},
		{"dir/nested/deep.txt", 'f', 0o640, "deep\n"},
		{"dir/link-up", 'l', 0, "../a.txt"},
		{"dir/link-dir", 'l', 0, "nested"},
		{"emptydir", 'd', 0o755, ""},
		{"emptydir-tight", 'd', 0o700, ""},
		{"hard.txt", 'h', 0, "a.txt"},
		{"pipe", 'p', 0o644, ""},
		{"self", 'l', 0, "."},
		{"z-link", 'l', 0, "dir/nested/deep.txt"},
		{"MiXeD-Case.TXT", 'f', 0o644, "mixed\n"},
		{"Zeta", 'd', 0o755, ""},
		{"Zeta/Inner.md", 'f', 0o644, "upper sorts first\n"},
		{"café-ñ.txt", 'f', 0o644, "non-ascii\n"},
		{"dir/" + longGoldenName, 'f', 0o644, "long\n"},
		{"sock", 's', 0, ""},
	}

	for _, e := range entries {
		p := filepath.Join(out, filepath.FromSlash(e.name))
		switch e.kind {
		case 'd':
			if err := os.MkdirAll(p, 0o755); err != nil {
				t.Fatal(err)
			}
		case 'f':
			if err := os.WriteFile(p, []byte(e.content), 0o644); err != nil {
				t.Fatal(err)
			}
		case 'l':
			if err := os.Symlink(e.content, p); err != nil {
				t.Fatal(err)
			}
			// macOS applies the umask to a symlink's mode; Linux always
			// reports 0777 and refuses to change it. Pin both to 0777.
			_ = unix.Fchmodat(unix.AT_FDCWD, p, 0o777, unix.AT_SYMLINK_NOFOLLOW)
		case 'h':
			if err := os.Link(filepath.Join(out, e.content), p); err != nil {
				t.Fatal(err)
			}
		case 'p':
			if err := syscall.Mkfifo(p, 0o644); err != nil {
				t.Fatal(err)
			}
		case 's':
			makeSocketFile(t, p)
		}
	}
	for _, e := range entries {
		if e.kind == 'd' || e.kind == 'f' || e.kind == 'p' {
			if err := os.Chmod(filepath.Join(out, filepath.FromSlash(e.name)), e.mode); err != nil {
				t.Fatal(err)
			}
		}
	}
	for i := len(entries) - 1; i >= 0; i-- {
		p := filepath.Join(out, filepath.FromSlash(entries[i].name))
		when := goldenEpoch.Add(time.Duration(i) * time.Minute)
		tv := []unix.Timeval{unix.NsecToTimeval(when.UnixNano()), unix.NsecToTimeval(when.UnixNano())}
		if err := unix.Lutimes(p, tv); err != nil {
			t.Fatal(err)
		}
	}
	return store
}

// makeSocketFile leaves a unix socket file at p. It is bound under a short
// directory and renamed into place, because a socket address is limited to
// about 100 bytes and test temp paths on macOS are longer than that.
func makeSocketFile(t *testing.T, p string) {
	t.Helper()
	short, err := os.MkdirTemp("/tmp", "sk")
	if err != nil {
		t.Fatal(err)
	}
	defer os.RemoveAll(short)
	fd, err := syscall.Socket(syscall.AF_UNIX, syscall.SOCK_STREAM, 0)
	if err != nil {
		t.Fatal(err)
	}
	defer syscall.Close(fd)
	bound := filepath.Join(short, "s")
	if err := syscall.Bind(fd, &syscall.SockaddrUnix{Name: bound}); err != nil {
		t.Fatal(err)
	}
	if err := os.Rename(bound, p); err != nil {
		t.Fatal(err)
	}
}

// describeTar lists every header field the walker sets, each entry's content
// digest, and the digest of the whole stream, so a byte-level difference
// anywhere in the archive shows up as a readable diff.
func describeTar(t *testing.T, archive []byte) string {
	t.Helper()
	var b strings.Builder
	tr := tar.NewReader(bytes.NewReader(archive))
	for {
		hdr, err := tr.Next()
		if err == io.EOF {
			break
		}
		if err != nil {
			t.Fatal(err)
		}
		body, err := io.ReadAll(tr)
		if err != nil {
			t.Fatal(err)
		}
		fmt.Fprintf(&b, "%c %-22s format=%v mode=%04o mtime=%d size=%d uid=%d gid=%d link=%q sha=%x\n",
			hdr.Typeflag, hdr.Name, hdr.Format, hdr.Mode, hdr.ModTime.Unix(), hdr.Size, hdr.Uid, hdr.Gid,
			hdr.Linkname, sha256.Sum256(body))
	}
	fmt.Fprintf(&b, "stream sha=%x len=%d\n", sha256.Sum256(archive), len(archive))
	return b.String()
}

// describeCopy lists a copied tree without following anything. Timestamps are
// left out because copyTree has never carried them.
func describeCopy(t *testing.T, dir string) string {
	t.Helper()
	var b strings.Builder
	err := filepath.WalkDir(dir, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		rel, err := filepath.Rel(dir, p)
		if err != nil {
			return err
		}
		if rel == "." {
			return nil
		}
		info, err := os.Lstat(p)
		if err != nil {
			return err
		}
		mode := info.Mode()
		switch {
		case mode&fs.ModeSymlink != 0:
			target, err := os.Readlink(p)
			if err != nil {
				return err
			}
			fmt.Fprintf(&b, "l %-22s link=%q\n", filepath.ToSlash(rel), target)
		case mode.IsDir():
			fmt.Fprintf(&b, "d %-22s mode=%04o\n", filepath.ToSlash(rel), mode.Perm())
		case mode.IsRegular():
			body, err := os.ReadFile(p)
			if err != nil {
				return err
			}
			fmt.Fprintf(&b, "f %-22s mode=%04o size=%d sha=%x\n", filepath.ToSlash(rel), mode.Perm(), len(body), sha256.Sum256(body))
		default:
			fmt.Fprintf(&b, "? %-22s mode=%v\n", filepath.ToSlash(rel), mode)
		}
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
	return b.String()
}

func compareGolden(t *testing.T, file, got string) {
	t.Helper()
	path := filepath.Join("testdata", file)
	if os.Getenv("TREE_WALK_GOLDEN_UPDATE") != "" {
		if err := os.MkdirAll("testdata", 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(path, []byte(got), 0o644); err != nil {
			t.Fatal(err)
		}
		t.Logf("wrote %s", path)
		return
	}
	want, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read golden %s: %v", path, err)
	}
	if string(want) == "" {
		t.Fatalf("golden %s is empty — this comparison cannot fail", path)
	}
	if got != string(want) {
		t.Errorf("output differs from %s\n--- want\n%s--- got\n%s", path, want, got)
	}
}

func TestTreeWalkGolden_Tar(t *testing.T) {
	store := buildGoldenTree(t)
	root, err := os.OpenRoot(store)
	if err != nil {
		t.Fatal(err)
	}
	defer root.Close()

	var archive bytes.Buffer
	if err := tarTree(&archive, root, goldenTreeLoc); err != nil {
		t.Fatalf("tarTree: %v", err)
	}
	compareGolden(t, "tree_walk_golden_tar.txt", describeTar(t, archive.Bytes()))
}

func TestTreeWalkGolden_Copy(t *testing.T) {
	store := buildGoldenTree(t)
	root, err := os.OpenRoot(store)
	if err != nil {
		t.Fatal(err)
	}
	defer root.Close()

	dst := t.TempDir()
	dstRoot, err := os.OpenRoot(dst)
	if err != nil {
		t.Fatal(err)
	}
	defer dstRoot.Close()

	if err := copyTree(context.Background(), root, goldenTreeLoc, dstRoot); err != nil {
		t.Fatalf("copyTree: %v", err)
	}
	compareGolden(t, "tree_walk_golden_copy.txt", describeCopy(t, dst))
}

// A mode-000 file. In production the daemon holds CAP_DAC_OVERRIDE and reads
// it; an unprivileged test process cannot, and both walkers have always
// failed on it with a permission error rather than skipping it. That
// unprivileged outcome is what is pinned here against the old walk; as root
// the entry is checked directly.
func TestTreeWalkGolden_ModeZeroFile(t *testing.T) {
	store := t.TempDir()
	out := filepath.Join(store, filepath.FromSlash(goldenTreeLoc))
	if err := os.MkdirAll(out, 0o755); err != nil {
		t.Fatal(err)
	}
	zero := filepath.Join(out, "zero")
	if err := os.WriteFile(zero, []byte("locked\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	if err := os.Chmod(zero, 0); err != nil {
		t.Fatal(err)
	}
	root, err := os.OpenRoot(store)
	if err != nil {
		t.Fatal(err)
	}
	defer root.Close()

	var archive bytes.Buffer
	tarErr := tarTree(&archive, root, goldenTreeLoc)

	dst := t.TempDir()
	dstRoot, err := os.OpenRoot(dst)
	if err != nil {
		t.Fatal(err)
	}
	defer dstRoot.Close()
	copyErr := copyTree(context.Background(), root, goldenTreeLoc, dstRoot)

	if os.Geteuid() != 0 {
		if !errors.Is(tarErr, fs.ErrPermission) {
			t.Errorf("tarTree: want a permission error, got %v", tarErr)
		}
		if !errors.Is(copyErr, fs.ErrPermission) {
			t.Errorf("copyTree: want a permission error, got %v", copyErr)
		}
		return
	}

	if tarErr != nil {
		t.Fatalf("tarTree: %v", tarErr)
	}
	hdr, err := tar.NewReader(&archive).Next()
	if err != nil || hdr.Name != "zero" || hdr.Mode != 0 || hdr.Size != 7 {
		t.Errorf("want zero carried with mode 0000 and its content, got %+v (%v)", hdr, err)
	}
	if copyErr != nil {
		t.Fatalf("copyTree: %v", copyErr)
	}
	info, err := os.Lstat(filepath.Join(dst, "zero"))
	if err != nil || info.Mode().Perm() != 0o444 {
		t.Errorf("want zero copied at mode 0444 (a+rX), got %v (%v)", info, err)
	}
}
